'use strict';
const COPY={"headline": "Find the right space for your business.", "opening": "Tell us a little about what you're looking for. We'll suggest locations and buildings worth exploring.", "headcount": "How many people need office space?", "headcount-helper": "An estimate is fine.", "shortcuts": "1 · 2 · 5 · 10 · 25 · 50", "uncertainty": "I'm not sure yet", "workspace": "What kind of workspace would suit you?", "first-action": "Show my starting points", "no-gate": "Free to explore. No name, email or account required.", "brief-title": "Your Location Brief", "district-section": "Here are a few areas we'd start with.", "building-section": "Here are the buildings we'd explore first.", "shortlist-introduction": "Based on what you've told us, these are a few places we'd start with. Each offers something different, and you can tell us which ones interest you.", "availability": "We haven’t confirmed that suitable space is available here yet.", "interested": "I'm interested", "refinement": "Want to explore something different?", "conversion-heading": "Want to take a closer look?", "conversion-description": "We can connect you with someone who knows these buildings and can help with availability, pricing or tours. There's no obligation, and you decide what happens next.", "optional-heading": "Anything else we should know?", "optional-helper": "A few more details can help us connect you with the right person. Share whatever you know.", "question-link": "Have a question about your search?", "question-description": "We're happy to help. Tell us what you're wondering about, and we'll get back to you by email.", "question-placeholder": "Anything you’d like us to know about your search?", "intro-heading": "Let's connect you with someone who can help.", "intro-permission": "Before we do, we'll show you who we're contacting and what information we'd share.", "intro-button": "Approve introduction", "decline": "Not right now", "inquiry-availability": "Check availability", "inquiry-pricing": "Get pricing and details", "inquiry-tour": "Ask about a tour", "inquiry-alternatives": "More options like this", "optional-budget": "Approximate budget", "optional-term": "Preferred lease length", "optional-growth": "Expected growth", "optional-message": "Additional requirements or questions", "district-Jackson Square-short": "Smaller historic buildings and quieter streets give Jackson Square a more intimate feel than the Financial District. It's worth exploring if a distinctive workplace or personal setting for client meetings matters to you.", "district-Jackson Square-expanded": "Jackson Square feels different from much of downtown San Francisco. Its smaller historic buildings, brick facades and quieter streets create a more intimate setting than the Financial District's office towers.\n\nFor a business that values a distinctive workplace or a more personal setting for client meetings, it's worth exploring.\n\nThe tradeoff is that older buildings can vary considerably in layout, accessibility and technical infrastructure. We'd want to investigate those details before recommending a particular space.", "district-Financial District-short": "A practical starting point for businesses that value regional transit access and a range of office settings, from traditional towers to older commercial buildings.", "district-Financial District-expanded": "The Financial District is San Francisco's traditional downtown business center, with office towers, older commercial buildings and convenient access to regional transit.\n\nIt's a practical starting point for companies whose employees or clients travel from different parts of the Bay Area. The district offers a variety of office environments, so we'd compare a few buildings before narrowing the search.\n\nThe important questions are how people get there, what kind of workplace the business needs, and what the total occupancy costs might be.", "district-Showplace Square-short": "Former industrial buildings, showrooms and a different street character make Showplace Square worth considering for teams that value flexible workplace settings or nearby design-related businesses.", "district-Showplace Square-expanded": "Showplace Square has a different character from downtown's traditional office districts. Its larger former industrial buildings, design showrooms and more open streets create a setting that can appeal to creative and design-oriented businesses.\n\nFor companies that regularly visit suppliers, showrooms or collaborators nearby, the location could make everyday work easier.\n\nBut proximity only matters if those relationships are part of how the business operates. We'd compare actual buildings, transportation and workspace requirements before recommending a location.", "building-why-office": "We'd consider this building if convenient access for your employees and clients is a priority. It offers a different office setting from some of the smaller buildings nearby.", "building-why-flex": "For a two-person team, a private office in a coworking center could give you a professional place to work without taking on a traditional office lease.", "building-check-office": "We'd want to confirm the available layouts, current pricing and whether the space could accommodate your team.", "building-check-flex": "We'd want to know which private offices are available, what the monthly price includes and how flexible the agreement is.", "availability-variable": "[Source] advertised approximately [size] of [space type] at [building] as of [date]. We'd confirm that it's still available before suggesting a tour.", "recipient-variable": "We'd like to share your [specific approved details] with [named recipient], who [represents the landlord / operates this workspace / could represent you]. Is that okay?", "after-introduction": "Your request has been shared with [recipient]. [Only describe follow-up Rofo actually performs.] A tour isn't confirmed until a time is agreed."};

let catalog=[];const app=document.getElementById('app'),dialog=document.getElementById('help');
let state={};
const names={cowork:'Office',office:'Office',retail:'Retail',industrial:'Industrial / Warehouse',flex:'Flex'};const districtNames={'financial-district':'Financial District',soma:'SoMa','jackson-square':'Jackson Square','north-waterfront':'North Waterfront','showplace-square':'Showplace Square','mid-market':'Mid-Market'};
const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function field(k,title,options){return `<div class="field"><label for="${k}">${title}</label><select id="${k}" name="${k}">${options.map(([v,t])=>`<option value="${v}" ${String(state.answers[k])===String(v)?'selected':''}>${t}</option>`).join('')}</select></div>`}
const districtEditorial={
'Mission District':{short:'A neighborhood commercial setting with maker, retail and cultural character.',fit:'A useful comparison for businesses serving local customers.',long:'The Mission’s researched examples include neighborhood-facing retail, maker and production-related uses. That context can help frame a search, but it does not establish customer demand for a particular business.',check:'We would investigate the actual block, premises, permitted use and physical requirements. Footfall, loading and parking are not verified.',basis:'Existing Rofo Mission District commercial-market evidence; occupied business examples are not available retail premises.',path:'mission-district'},
'Design District':{short:'A design-trade setting shaped by showrooms and related businesses.',fit:'Worth comparing for a destination-led business with relevant trade relationships.',long:'The Design District’s researched examples emphasize showroom, design-trade and adaptive commercial settings. The cluster may matter for a business whose customers or collaborators already have reasons to visit.',check:'We would check whether those relationships matter to this business, and investigate actual premises, arrival routes, loading and permitted use.',basis:'Existing Rofo Design District evidence. The neighboring Showplace Square creative-office context is distinct; no available retail premises are established.',path:'design-district'},
'Jackson Square':{short:'Smaller historic buildings and a more intimate setting than downtown’s office towers.',fit:'Worth exploring if character and a personal setting for client meetings matter.',long:'Jackson Square offers a boutique, historic-building comparison to the Financial District’s larger office environment. That character may appeal to a business that wants a distinctive workplace or client setting.',check:'Older premises can differ in layout, accessibility and technical infrastructure. We would check the actual building rather than assume those qualities.',basis:'Existing Rofo Jackson Square district/building research; exact quietness, facade and street conditions are not established here.',path:'jackson-square'},
'Financial District':{short:'San Francisco’s traditional downtown business setting, with a range of office buildings.',fit:'A useful starting point when employees or clients arrive from different parts of the Bay Area.',long:'The Financial District brings together conventional office towers and older commercial buildings. Regional transit is part of its appeal, but the best address depends on where your people travel from and the workplace you need.',check:'Compare the real commute, building layout and full occupancy costs. We have not calculated a journey time or confirmed a suite.',basis:'Existing Rofo Financial District commercial-market evidence. Regional transit is a district-level starting point, not a building-specific journey guarantee.',path:'financial-district'},
'Showplace Square':{short:'A different workplace setting, with former industrial and creative-commercial character.',fit:'Worth comparing if nearby design, supplier or collaborator relationships matter to your business.',long:'Showplace Square provides a creative-office comparison to downtown’s conventional office districts. Research describes brick-and-timber and production-adjacent workplace character. Nearby showrooms can be relevant, but only when those relationships are part of how the business operates.',check:'The neighboring Design District has a distinct showroom role. We would check the address, travel and actual workspace instead of treating the two district names as interchangeable.',basis:'Existing Rofo Showplace Square and neighboring Design District evidence. The proposal does not establish more-open streets or a new district boundary.',path:'showplace-square'},
'SoMa':{short:'A broad central-city comparison with technology and creative-office settings.',fit:'Worth considering alongside downtown towers if a different workplace format appeals.',long:'SoMa offers a broader central-city office comparison, including technology-oriented and adaptive commercial settings. The experience can change considerably from one address to another.',check:'Check the particular building, walking route and agreement. A district label does not establish a suitable office or a convenient commute.',basis:'Existing Rofo neighboring-district comparisons and address-based operator research; no new boundary or journey-time claim.',path:'soma'}
};
function approvedDistrictCards(){let rows=[];if(state.scenario==='retail'){const a=state.answers;rows=a.business==='showroom'||a.priority==='trade'||a.physical==='loading'?[['Design District','Compare a design-trade setting for destination customers and a showroom.','Loading, customer parking and the actual permitted use need a property-level check.','https://www.rofo.com/commercial-real-estate/CA/san-francisco/design-district/'],['Mission District','A neighborhood and maker-retail comparison if local customers or a public-facing workshop matter.','Demand on a specific block, loading and physical fit are not established.','https://www.rofo.com/commercial-real-estate/CA/san-francisco/mission-district/']]:a.customers==='workers'?[['Financial District','Worth comparing when nearby office workers are your intended customers.','Actual trading patterns, weekend demand and storefront suitability need checking.','https://www.rofo.com/commercial-real-estate/CA/san-francisco/financial-district/'],['Mission District','A contrasting neighborhood customer base rather than relying entirely on office-worker demand.','Neither footfall counts nor demand at a particular storefront are verified.','https://www.rofo.com/commercial-real-estate/CA/san-francisco/mission-district/']]:[['Mission District',a.customers==='destination'?'Compare a neighborhood commercial setting as an alternative for customers making a planned visit. This is not proof of a destination retail fit.':'Start by comparing a neighborhood commercial setting for a shop serving nearby residents.','A busy district is not proof of foot traffic or demand at a particular storefront.','https://www.rofo.com/commercial-real-estate/CA/san-francisco/mission-district/'],['Design District',a.customers==='destination'?'A design-trade comparison if your planned-visit business benefits from related businesses nearby.':'A different starting point if your business becomes more destination-led or design-focused.','Trade-cluster relevance is not a substitute for customer research or a suitable shopfront.','https://www.rofo.com/commercial-real-estate/CA/san-francisco/design-district/']];}else{rows=[['Financial District',state.scenario==='office'?'Compare a conventional downtown office setting for your team, especially if transit access matters.':'A practical place to compare several shared and private-workspace formats downtown.','Check each address against your actual commute; centrality alone does not establish convenience.','financial-district'],['SoMa',state.scenario==='office'?'An alternative to conventional downtown towers, with broader technology and creative-office context.':'A contrasting location if a dedicated desk or a private office near Mission Street appeals.','Building formats and walking routes differ considerably; no suitable available suite is confirmed.','soma'],[state.scenario==='office'?'Showplace Square':'Jackson Square',state.scenario==='office'?'Compare a wider-area workplace at 100 Hooper if conventional downtown space feels too formal.':'Compare communal memberships if a smaller-scale setting matters more than a conventional tower.','Check the specific route, agreement and physical space before deciding.',state.scenario==='office'?'showplace-square':'jackson-square']];if(state.scenario==='office'&&state.answers.commute==='character')rows=[rows[2],rows[1],rows[0]];}return rows.map(([n,why,trade,d])=>{const ed=districtEditorial[n],exampleShort=COPY['district-'+n+'-short'],exampleLong=COPY['district-'+n+'-expanded'];return `<article class="district"><h3>${n}</h3><p>${exampleShort?E(exampleShort):ed?ed.short:why}</p>${exampleShort?'<p class="copy-review-note">Working editorial example · factual verification required before publication.</p>':''}${state.scenario==='retail'?`<p class="small">${why}</p>`:exampleShort?'':`<p class="small">${ed?ed.fit:trade}</p>`}<details class="district-more"><summary>Get to know ${n}</summary>${exampleLong?exampleLong.split('\n\n').map(x=>`<p>${E(x)}</p>`).join(''):`<p>${ed?ed.long:why}</p>`}<div class="source-notes"><p class="small">${exampleLong?'Separate evidence note — the exemplar above is a working draft. ':''}${ed?ed.check:trade}</p></div><p class="small">${ed?ed.basis:'Existing Rofo district evidence; current customer demand, footfall and suitable premises are not confirmed.'} No review date is recorded for the district source files.</p><a href="${state.scenario==='retail'?d:'https://www.rofo.com/commercial-real-estate/CA/san-francisco/'+(ed?.path||d)+'/'}" target="_blank" rel="noopener">Explore the district ↗</a></details>${state.scenario==='retail'?'':`<button data-district="${d}">See starting points here</button>`}</article>`}).join('')}
function why(p){const a=state.answers;if(state.scenario==='office'){if(p.id==='350')return `For ${a.people==null?'your team':a.people+' people'}, this gives you a different office-layout comparison. An actual suite and fit-out plan still need checking.`;if(p.id==='555')return `A conventional downtown office benchmark for your ${a.people==null?'team':a.people+'-person team'}, to compare with serviced space.`;if(p.id==='hooper')return `A wider-area traditional-office comparison if a different workplace setting matters. Team capacity is not verified.`;return `A serviced-office approach could reduce what your ${a.people==null?'team':a.people+'-person team'} has to manage. ${a.use==='hybrid'?'Compare named-user rights with your actual peak attendance.':'Check capacity for the whole team on busy days.'} No suitable office or team price is verified.`;}if(p.type==='shared-membership'){if(p.locationId==='pac315')return 'A way to try shared workspace by the day before deciding whether a longer commitment suits you.';if(p.locationId==='werq465')return `A monthly shared-lounge comparison for ${a.people==null?'each named person':a.people+' named people'}. Confirm access rights and places to work together.`;if(p.locationId==='canopy')return 'A communal-workspace alternative in Jackson Square. Compare the membership rules with your expected attendance.';return `A shared-workspace comparison for ${a.people==null?'your team':a.people+' people'}; dedicated desks and flexible lounge access are different products.`;}return `An enclosed-office alternative for ${a.people==null?'your team':a.people+' people'} if privacy matters more than communal workspace. Actual office capacity must be checked.`}
function card(p){return `<article class="card"><div class="image" aria-label="Illustrated building placeholder, not a photograph"><span>Building illustration · not a photograph</span></div><div class="cardbody"><div class="tag">${p.type==='shared-membership'?'Shared workspace':p.type==='traditional-lease'?'Traditional office lease':'Private serviced office'}</div><p class="small product-format">${E(p.productName)}</p><h3>${E(p.name)}</h3><p class="small">${E(p.address)}<br>${E(p.operator)}</p><p class="why">${why(p)}</p><div class="facts"><strong>What it costs</strong>${E(p.price)}</div><details><summary>What we know &amp; what needs checking</summary><p><strong>Privacy</strong> ${E(p.privacy)}</p><p><strong>Commitment</strong> ${E(p.commitment)}</p><p>${E(p.sourceFact)}</p><p>${E(p.access)}</p><p>${E(p.qualifications.join(' ').replaceAll('working location group; not an adopted Rofo polygon','Location grouped for this comparison; exact district boundary not established.').replaceAll('inquiry lead','a reason to ask about an office').replaceAll('Working address-based comparison; not a new adopted Rofo polygon.','Address-based comparison; exact district boundary not established.'))}</p><p>Research checked ${E(p.sourceAccessed)}. Source publication date not established. This proposal has not refreshed the evidence.</p><a href="${E(p.sourceUrl)}" target="_blank" rel="noopener">Original source ↗</a></details><button class="primary" data-help="${p.id}">${E(COPY.interested)}</button><div class="tools"><button class="textbutton" data-save="${p.id}" aria-pressed="${state.saved.includes(p.id)}">${state.saved.includes(p.id)?'Saved ✓':'Save'}</button><button class="textbutton" data-compare="${p.id}" aria-pressed="${state.compare.includes(p.id)}">${state.compare.includes(p.id)?'In comparison ✓':'Compare'}</button><button class="textbutton" data-dismiss="${p.id}">Not for me</button></div></div></article>`}
function compare(){let list=optionPool().filter(p=>state.compare.includes(p.id));return list.length?`<section class="panel comparison"><h2>Compare your options</h2><p class="small">${list.length===1?'Choose Compare on another card to see the differences.':'Compare formats and commitments before asking for current details.'}</p><table><thead><tr><th>Option</th><th>Workspace</th><th>What it costs</th><th>Commitment</th></tr></thead><tbody>${list.map(p=>`<tr><th>${E(p.name)}<br><button class="textbutton" data-compare="${p.id}">Remove</button></th><td>${E(p.productName)}</td><td>${E(p.price)}</td><td>${E(p.commitment)}</td></tr>`).join('')}</tbody></table></section>`:''}
function questionSection(){return `<details class="question-box"><summary>Have a question about your search?</summary><p>${E(COPY["question-description"])}</p><p class="small">Your current Brief is included automatically. This is a question for Rofo, not a broker introduction. Rofo reviews your question. No automatic outside inquiry is sent.</p><form id="rofo-question"><label for="questionMessage">Your question</label><textarea id="questionMessage" name="message" required maxlength="600" placeholder="${E(COPY['question-placeholder'])}"></textarea><label for="questionEmail">Your email</label><input id="questionEmail" name="email" type="email" required placeholder="you@company.com"><button class="secondary" style="margin-top:12px">Preview my question</button><p id="question-status" role="status" class="small"></p></form></details>`}
function approvedBrief(){const s=state.scenario,a=state.answers;const items=s==='retail'?[]:options();return `<h1>${E(COPY["brief-title"])}</h1><p class="intro">${s==='retail'?'Here are a few areas worth exploring for your business.':E(COPY['shortlist-introduction'])}</p><details class="panel" id="editbox"><summary>Change your answers · ${s==='retail'?'Retail in San Francisco':(a.people==null?'Team size not sure':E(a.people)+' people')+' · San Francisco'}</summary>${form(true)}</details><p class="small">${s==='retail'?'Starting point: district comparisons, not a claim of suitable available shopfronts.':`Starting point: ${a.people==null?'team size not yet known':E(a.people)+' people'} · ${E(workspaceLabels[state.requirements.workspace])}. No suite size, rent or fit-out budget assumed.`}</p><div class="sectionhead"><div><span class="eyebrow">Where we’d look</span><h2>${E(COPY['district-section'])}</h2></div></div><details class="area-details" ${s==='retail'||innerWidth>560?'open':''}><summary>Why these areas? See the tradeoffs.</summary><div class="tiles" style="margin-top:14px">${districtCards()}</div></details>${s==='retail'?`<section class="callout"><h2>${state.requirements.district&&!['mission-district','design-district'].includes(state.requirements.district)?'More research is needed for this area.':'Useful district guidance. More property research needed.'}</h2><p>Our current reviewed material does not support a shortlist of suitable retail premises for this search. We won’t substitute office buildings or occupied shops.</p><p>${a.physical==='food'||a.business==='food'?'For food or drink, permission for the intended use, ventilation and utilities need checking at an actual premises.':a.priority==='parking'?'We have not verified customer parking at any premises. Make that part of the next investigation.':'The next step is to investigate actual storefronts, permitted use and the customer pattern on a specific block.'}</p><p class="small">District guidance uses existing Rofo Mission District, Design District and Financial District research. No source review date is recorded in those files; current footfall, vacancy and parking are unverified.</p><button class="primary" data-help="retail">Help me find suitable premises</button></section>`:`<div class="sectionhead"><div><h2>${E(COPY["building-section"])}</h2></div><span class="savedCount">${state.saved.length} saved · ${state.dismissed.length} dismissed</span></div><p class="small">Starting points from research checked October 29, 2026. ${E(COPY.availability)}${s==='office'?' No team-sized suite, rent or capacity is established.':''}</p><div class="chips" aria-label="Refine starting points"><button class="chip" data-filter="all" aria-pressed="${state.district==='all'}">All suggested areas</button>${['financial-district','soma',s==='office'?'showplace-square':'jackson-square'].map(d=>`<button class="chip" data-filter="${d}" aria-pressed="${state.district===d}">${districtNames[d]}</button>`).join('')}${s==='cowork'?`<button class="chip" data-format="shared" aria-pressed="${state.format==='shared'}">Shared only</button><button class="chip" data-format="private" aria-pressed="${state.format==='private'}">Private only</button><button class="chip" data-format="all" aria-pressed="${state.format==='all'}">Both formats</button>`:''}</div><p class="live" role="status" aria-live="polite">${E(state.notice)}</p><div class="grid">${items.length?items.map(card).join(''):`<div class="empty"><h3>We don’t have another supported option here yet.</h3><p>We haven’t widened your location or privacy choices. Try another area, restore a dismissed option or ask us to investigate.</p><button class="secondary" data-help="research">Ask Rofo to look further</button></div>`}</div><h2>${E(COPY.refinement)}</h2><div class="actions" style="margin-top:20px"><button class="quiet" id="more">Show other researched starting points</button>${state.dismissed.length?'<button class="quiet" id="restore">Restore dismissed options</button>':''}</div>${state.saved.length?`<details class="panel"><summary>Saved options (${state.saved.length})</summary><ul>${catalog.filter(p=>state.saved.includes(p.id)).map(p=>`<li>${E(p.name)} — ${E(p.productName)}</li>`).join('')}</ul><p class="small">Your saves stay available when you change the shortlist. A saved option is not a reservation.</p></details>`:''}${compare()}<div class="callout split"><div><h2>Want to take a closer look?</h2><p class="muted">${E(COPY["conversion-description"])}</p></div><button class="primary" data-help="research">${E(COPY.interested)}</button></div>`}${questionSection()}<p class="small" style="margin-top:26px">Explore for free. If you later want an introduction, we’ll explain who would receive your details and ask first. Rofo may earn compensation from a permitted introduction; relevance comes first.</p>`}
let helpItem,helpPurpose;function openHelp(id){helpItem=id;helpPurpose='';let p=catalog.find(p=>p.id===id);dialog.innerHTML=`<button class="close" aria-label="Close">×</button><div class="eyebrow">A little more help</div><h2 id="helpTitle">${p?'What would you like to find out?':'What should we look into?'}</h2><p>${p?E(p.name):'Your current answers and saved options will travel with this request.'}</p><form id="purpose">${(p?[['research',COPY['inquiry-alternatives']],['availability',COPY['inquiry-availability']],['pricing','Get pricing and details'],['tour',COPY['inquiry-tour']],['broker','Help from a commercial real estate professional']]:[['research',COPY['inquiry-alternatives']],['availability',COPY['inquiry-availability']],['pricing','Get pricing and details'],['tour',COPY['inquiry-tour']],['broker','Help from a commercial real estate professional']]).map(([v,t])=>`<label class="radio"><input type="radio" name="purpose" value="${v}" required>${t}</label>`).join('')}<button class="primary">Continue</button></form><p class="small">No availability, quote, tour or introduction is confirmed. Outside sharing requires a separate named-recipient permission step.</p>`;dialog.showModal();dialog.querySelector('.close').onclick=()=>dialog.close();document.getElementById('purpose').onsubmit=e=>{e.preventDefault();helpPurpose=new FormData(e.target).get('purpose');helpContact()}}
function closeHelp(){dialog.close()}
function helpContact(){dialog.innerHTML=`<button class="close" aria-label="Close">×</button><h2 id="helpTitle">Let’s make the next step useful.</h2><p>Rofo can help investigate this option or connect you with an appropriate person. We’ll explain their role and ask before sharing your details.</p><form id="contact"><div class="field"><label for="followemail">Your email</label><input id="followemail" type="email" name="email" placeholder="you@company.com" required></div><details class="optional-details"><summary>Anything else we should know?</summary><p class="small">A few more details can help us connect you with the right person. Share whatever you know.</p><label for="budget">Approximate budget <span class="small">optional</span></label><input id="budget" name="budget" maxlength="80" placeholder="For example, $5,000/month for the team"><div class="field"><label for="term">${E(COPY["optional-term"])}</label><select id="term" name="term"><option value="Not specified">No preference yet</option><option>Month-to-month if possible</option><option>Around one year</option><option>A longer agreement could work</option></select></div><div class="field"><label for="growth">Expected growth</label><select id="growth" name="growth"><option value="Not specified">Not sure yet</option><option>About the same team</option><option>A few more people</option><option>Significant growth expected</option></select></div><label for="note">Additional requirements or questions</label><textarea id="note" name="note" maxlength="600" placeholder="Anything that would make the space work better for you"></textarea></details><label class="check"><input type="checkbox" required>I’d like Rofo to review this request and reply to me. This does not authorize an introduction.</label><button class="primary">Preview my request</button></form><p class="small">Your request stays with Rofo for review. An introduction requires your separate permission.</p>`;dialog.querySelector('.close').onclick=closeHelp;document.getElementById('contact').onsubmit=e=>{e.preventDefault();const data=new FormData(e.target),p=catalog.find(x=>x.id===helpItem),payload={email:String(data.get('email')),answers:answerText(),option:p?.name||'District guidance / current starting points',budget:String(data.get('budget')||'Not specified'),term:String(data.get('term')),growth:String(data.get('growth')),note:String(data.get('note')||'None'),purpose:helpPurpose};showRequest(payload,p)}}
// Isolated local review only. One active requirements object; the original entry is immutable provenance.
let marketRegistry=[],entryOrigin,storageKey,editOpen=false;
const typeLabels={office:'Office',retail:'Retail',industrial:'Industrial / Warehouse',flex:'Flex'};
const workspaceLabels={either:'Open to either',private:'Private office',cowork:'Coworking / shared space',traditional:'Traditional office lease'};
const retailLabels={shop:'Shop / boutique',food:'Restaurant / café',service:'Service business',showroom:'Showroom',unsure:'Other / not sure'};
const useLabels={warehouse:'Storage and deliveries',production:'Production / workshop',showroom:'Showroom',workshop:'Light production / workshop',storage:'Office with storage',unsure:"I'm not sure yet"};
function freshRequirements(type='',city=''){return {type,city,people:'',workspace:'either',size:'',business:'unsure',use:'unsure',district:''}}
function cityRecord(value){const q=String(value||'').trim().toLowerCase();return marketRegistry.find(m=>m.l.toLowerCase()===q)||null}
function isSF(){return cityRecord(state.requirements.city)?.slug==='san-francisco'&&cityRecord(state.requirements.city)?.state==='CA'}
function presentationScenario(){const r=state.requirements;if(r.type==='retail')return 'retail';if(r.type!=='office')return r.type;return r.workspace==='cowork'||(r.workspace!=='traditional'&&typeof r.people==='number'&&r.people<=5)?'cowork':'office'}
function derivedAnswers(){const r=state.requirements;return {people:typeof r.people==='number'?r.people:null,peak:null,privacy:r.workspace==='cowork'?'open':r.workspace==='either'?'either':'private',area:'any',use:'unsure',commute:'unsure',business:r.business,customers:'unsure',priority:r.business==='showroom'?'trade':'foot',physical:r.business==='food'?'food':'standard'}}
function attachDerived(){Object.defineProperties(state,{scenario:{get:presentationScenario},answers:{get:derivedAnswers},district:{get:()=>state.requirements.district||'all',set:v=>state.requirements.district=v==='all'?'':v},format:{get:()=>state.requirements.workspace==='cowork'?'shared':state.requirements.workspace==='private'?'private':'all',set:v=>state.requirements.workspace=v==='shared'?'cowork':v==='private'?'private':'either'}})}
function persist(){try{sessionStorage.setItem(storageKey,JSON.stringify({requirements:state.requirements,brief:state.brief,saved:state.saved,dismissed:state.dismissed,compare:state.compare,more:state.more,notice:state.notice,serverRevision:liveBrief?.revision}))}catch{}}
function initializeEntry(){const q=entryParameters(),entry=['home','city','district','building'].includes(q.get('entry'))?q.get('entry'):'home';let type=Object.hasOwn(typeLabels,q.get('type'))?q.get('type'):'',city=q.get('city')||'',building=null,district='';if(entry==='home'&&!q.has('fixture')){city='';type=''}if(entry==='building'){building=catalog.find(p=>p.id===q.get('building'))||catalog.find(p=>p.locationId===q.get('building'));if(building){city='San Francisco, CA';type='office'}}if(entry==='district'&&cityRecord(city)?.slug==='san-francisco'&&districtNames[q.get('district')])district=q.get('district');entryOrigin=Object.freeze({entry,city,type,district,building:building?{id:building.id,name:building.name,address:building.address,sourceUrl:building.sourceUrl}:entry==='building'&&q.get('buildingName')?{id:q.get('building')||'',name:q.get('buildingName'),address:q.get('address')||''}:null});let req=freshRequirements(type,city);req.district=district;if(type==='office'){const n=Number(q.get('people'));if(q.has('people')&&Number.isInteger(n)&&n>0)req.people=n;if(Object.hasOwn(workspaceLabels,q.get('workspace')))req.workspace=q.get('workspace')}if(type==='retail'&&Object.hasOwn(retailLabels,q.get('business')))req.business=q.get('business');if(['industrial','flex'].includes(type)&&Object.hasOwn(useLabels,q.get('use')))req.use=q.get('use');storageKey='rofoUniversalEntry:'+location.pathname+location.search;let saved=null;try{saved=JSON.parse(sessionStorage.getItem(storageKey))}catch{}state={requirements:req,brief:false,saved:[],dismissed:[],compare:[],more:0,notice:''};if(saved?.requirements&&Object.hasOwn(typeLabels,saved.requirements.type)){Object.assign(state,saved)}attachDerived();if(boot.publicId){liveBrief={publicId:boot.publicId,revision:boot.revision};state.requirements=saved?.serverRevision===boot.revision?saved.requirements:boot.requirement.initialSearch;entryOrigin=Object.freeze(boot.originalEntry);state.brief=true;} }
function clearResultState(){inquiryRows=[];state.saved=[];state.dismissed=[];state.compare=[];state.more=0;state.notice='';if(dialog.open)dialog.close();dialog.innerHTML=''}
function retainCompatibleFeedback(){inquiryRows=[];const ids=new Set(optionPool().map(p=>p.id));state.saved=state.saved.filter(x=>ids.has(x));state.compare=state.compare.filter(x=>ids.has(x));state.more=0;if(dialog.open)dialog.close();dialog.innerHTML=''}
function collectForm(form){const r=state.requirements,data=new FormData(form);r.city=String(data.get('city')??r.city);if(r.type==='office'){const n=data.get('people');r.people=n===''?(r.people===null?null:''):Number(n);r.workspace=String(data.get('workspace')||r.workspace)}if(r.type==='retail')r.business=String(data.get('business')||'unsure');if(r.type==='industrial'){const n=data.get('size');r.size=n===''?(r.size===null?null:''):Number(n);r.use=String(data.get('use')||'unsure')}if(r.type==='flex')r.use=String(data.get('use')||'unsure')}
function changeType(type){const initialDistrict=!state.requirements.type?state.requirements.district:'';const city=String(document.getElementById('city')?.value??state.requirements.city);state.requirements=freshRequirements(type,city);state.requirements.district=initialDistrict;clearResultState();render();if(state.brief){editOpen=true;document.getElementById('editbox').open=true}document.querySelector('[data-type="'+type+'"]')?.focus()}
function marketField(){return `<div class="field market-field"><label for="city">Where are you looking?</label><div class="market-search-control"><input id="city" name="city" type="search" value="${E(state.requirements.city)}" placeholder="City or market" autocomplete="off" role="combobox" aria-autocomplete="list" aria-controls="city-results" aria-expanded="false" required><div id="city-results" class="search-results" role="listbox" hidden></div></div></div>`}
function headcount(){const n=state.requirements.people;return `<div class="field"><label for="people">${E(COPY.headcount)}</label><input id="people" name="people" type="number" min="1" step="1" inputmode="numeric" value="${n??''}" placeholder="${n===null?'Not sure yet':'For example, 17'}" ${n===null?'':'required'}><div class="chips count-shortcuts" aria-label="Headcount shortcuts">${[1,2,5,10,25,50].map(x=>`<button type="button" class="chip" data-count="${x}" aria-pressed="${n===x}">${x}</button>`).join('')}<button type="button" class="textbutton" data-count="unknown" aria-pressed="${n===null}">${E(COPY.uncertainty)}</button></div></div>`}
function fields(){const r=state.requirements;if(!r.type)return '';let out=marketField();if(r.type==='office')return out+headcount()+`<div class="field"><label for="workspace">${E(COPY.workspace)}</label><select id="workspace" name="workspace">${Object.entries(workspaceLabels).map(([v,t])=>`<option value="${v}" ${r.workspace===v?'selected':''}>${t}</option>`).join('')}</select></div>`;if(r.type==='retail')return out+`<div class="field"><label for="business">What kind of retail business?</label><select id="business" name="business">${Object.entries(retailLabels).map(([v,t])=>`<option value="${v}" ${r.business===v?'selected':''}>${t}</option>`).join('')}</select></div>`;if(r.type==='industrial')return out+`<div class="field"><label for="size">About how much space do you need?</label><div class="unit-input"><input id="size" name="size" type="number" min="1" step="any" value="${r.size??''}" placeholder="${r.size===null?'Not sure yet':'Approximate size'}" ${r.size===null?'':'required'}><span>sq ft</span></div><button type="button" class="textbutton" id="size-unknown">${E(COPY.uncertainty)}</button></div><div class="field"><label for="use">What will happen there?</label><select id="use" name="use"><option value="unsure">${E(COPY.uncertainty)}</option>${['warehouse','production'].map(v=>`<option value="${v}" ${r.use===v?'selected':''}>${useLabels[v]}</option>`).join('')}</select></div>`;return out+`<div class="field"><label for="use">How will you use the space?</label><select id="use" name="use"><option value="unsure">${E(COPY.uncertainty)}</option>${['showroom','workshop','storage'].map(v=>`<option value="${v}" ${r.use===v?'selected':''}>${useLabels[v]}</option>`).join('')}</select></div>`}
function districtPreference(){const d=state.requirements.district;return d?`<p class="entry-preference">Starting with ${E(districtNames[d])}. <button type="button" class="textbutton" id="clear-district">Compare other areas</button></p>`:''}
function form(edit=false){return `<form id="answers"><fieldset class="type-select"><legend>What kind of space are you looking for?</legend><div class="type-options">${Object.entries(typeLabels).map(([k,label])=>`<button type="button" data-type="${k}" aria-pressed="${state.requirements.type===k}">${label}</button>`).join('')}</div></fieldset>${state.requirements.type?`<div class="fields entry-fields ${state.requirements.type}">${fields()}</div>${districtPreference()}`:''}${edit?`<button type="button" class="quiet" id="back-brief">Back to my Location Brief</button>`:`<div class="actions"><button class="primary" ${state.requirements.type?'':'disabled'}>${E(COPY['first-action'])}</button></div><p class="small trust">${E(COPY['no-gate'])}</p>`}</form>`}
function optionPool(){return initialOptions(state.requirements)}
function options(){return optionPool().filter(p=>!state.dismissed.includes(p.id)).slice(state.more,state.more+4)}
function provenance(){if(entryOrigin.entry==='home'&&!entryOrigin.city&&!entryOrigin.building)return '';return `<details class="origin-context"><summary>Where this search started</summary><p>${entryOrigin.building?E(entryOrigin.building.name)+' · '+E(entryOrigin.building.address):entryOrigin.district?E(districtNames[entryOrigin.district])+' · '+E(entryOrigin.city):E(entryOrigin.city)}</p><p class="small">This original reference is retained for context. It does not limit your current search.</p></details>`}
function guidanceDistricts(){const r=state.requirements;let rows=[];if(!isSF())return '';if(r.type==='retail'){let order=r.business==='showroom'?['Design District','Mission District']:['Mission District','Design District'];if(r.district)order=order.filter(n=>n.toLowerCase().replaceAll(' ','-')===r.district);if(!order.length)return '<p>We need more retail research for this area. Compare other areas only if you want to widen your search.</p>';return order.map(n=>{const e=districtEditorial[n];return `<article class="district"><h3>${n}</h3><p>${e.short}</p><details class="district-more"><summary>Get to know ${n}</summary><p>${e.long}</p><p class="small">${e.check}</p><p class="small">${e.basis} No review date is recorded in the district source file.</p><a href="https://www.rofo.com/commercial-real-estate/CA/san-francisco/${e.path}/" target="_blank" rel="noopener">Explore the district ↗</a></details></article>`}).join('')}const industrial=[['Bayview Industrial','A warehouse and city-serving logistics comparison. Actual loading, power, yard rights and permitted use need checking.','bayview-industrial'],['Central Waterfront','A comparison for urban production, fabrication and practical flex uses. The actual premises and operating rights still need investigation.','central-waterfront']];if(r.type==='flex'&&r.use==='showroom')rows=[['Design District',districtEditorial['Design District'].short,'design-district'],industrial[1]];else if(r.type==='flex'||r.use==='production')rows=[industrial[1],industrial[0]];else rows=industrial;if(r.district)rows=rows.filter(row=>row[2]===r.district);if(!rows.length)return '<p>We need more research for this area and use. We haven’t widened your search.</p>';return rows.map(([name,copy,id])=>`<article class="district"><h3>${name}</h3><p>${copy}</p><p class="small">District context only. No suitable property, loading allowance or available space is confirmed.</p><a href="https://www.rofo.com/commercial-real-estate/CA/san-francisco/${id}/" target="_blank" rel="noopener">Explore the district ↗</a></article>`).join('')}
function districtCards(){return state.requirements.type==='retail'?guidanceDistricts():approvedDistrictCards()}
function brief(){if(isSF()&&['office','retail'].includes(state.requirements.type))return approvedBrief();const r=state.requirements,hasDistricts=isSF()&&['industrial','flex'].includes(r.type);return `<h1>${E(COPY['brief-title'])}</h1><p class="intro">${E(typeLabels[r.type])} · ${E(r.city)}</p><details class="panel" id="editbox"><summary>Change your answers</summary>${form(true)}</details><section class="panel"><h2>Your search</h2><p>${E(answerText())}</p></section>${hasDistricts?`<h2>${E(COPY['district-section'])}</h2><div class="tiles">${guidanceDistricts()}</div>`:''}<section class="callout"><h2>More property research is needed.</h2><p>${hasDistricts?'We can show useful district comparisons, but this local preview does not contain a reviewed property shortlist for these requirements.':'This local preview does not yet contain a researched shortlist for this location and space type.'}</p><p>This is a research-coverage limit, not a claim that suitable space is unavailable. We haven’t substituted San Francisco office options or widened your requirements.</p>${r.type==='industrial'||r.type==='flex'?'<p class="small">Loading, power, yard or storage rights, the intended use and actual premises need checking. The space requirement is not a claim of available area or property capability.</p>':''}<button class="secondary" data-help="research">Ask Rofo to look further</button></section>${questionSection()}`}
function canonicalProjection(){const r=state.requirements,c=cityRecord(r.city),activities=r.type==='office'?['work']:r.type==='industrial'?(r.use==='warehouse'?['store','ship_distribute']:r.use==='production'?['make_assemble']:[]):r.type==='flex'?(r.use==='showroom'?['display_present','host_visitors']:r.use==='workshop'?['make_assemble','prototype']:r.use==='storage'?['work','store']:[]):[];const requirement={propertyTypes:r.type?[r.type==='retail'?'retail_service':['industrial','flex'].includes(r.type)?'industrial_flex':'office']:[],locationLogic:{marketAnchor:{marketId:c?.slug||'',displayName:r.city,state:c?.state||''},specificPreference:{candidateDistrictIds:r.district?[r.district]:[]}},activities,businessContext:{summary:r.type==='retail'?retailLabels[r.business]:['industrial','flex'].includes(r.type)?useLabels[r.use]:'Office workspace'},sizeCapacity:{summary:r.type==='office'?(typeof r.people==='number'?`${r.people} people need access; peak attendance and area unknown`:'Headcount not yet known'):r.type==='industrial'&&typeof r.size==='number'?`Approximately ${r.size} sq ft requested`:'Size not yet known'}};return {requirement,industrialFlexIntent:['industrial','flex'].includes(r.type)?industrialAdapter.resolveIntent(requirement):null,workspacePreference:r.type==='office'?r.workspace:null,originalEntry:entryOrigin}}
function answerText(){const r=state.requirements;let text=[typeLabels[r.type]||'Space type not chosen',r.city||'Location not chosen'];if(r.type==='office')text.push(typeof r.people==='number'?r.people+' people':'Headcount not sure',workspaceLabels[r.workspace]);if(r.type==='retail')text.push(retailLabels[r.business]);if(r.type==='industrial')text.push(typeof r.size==='number'?'Approximately '+r.size+' sq ft':'Size not sure',useLabels[r.use]);if(r.type==='flex')text.push(useLabels[r.use]);if(r.district)text.push('Starting district: '+districtNames[r.district]);return text.join(' · ')}
function render(){app.innerHTML=`${state.brief?brief():`<h1>${E(COPY.headline)}</h1><p class="intro">${E(COPY.opening)}</p><section class="panel entry-panel">${form()}</section>`}${provenance()}${requestMarkup()}<footer class="footer">Original research dates remain visible · No operator photographs used.<br>No automatic external inquiries are sent. <button class="reset" id="reset">Start a new search</button></footer><script type="application/json" id="requirement-projection">${JSON.stringify(canonicalProjection()).replace(/</g,'\\u003c')}<\/script>`;bind();persist()}
function refreshEditing(focus){editOpen=true;render();if(document.getElementById('editbox'))document.getElementById('editbox').open=true;if(focus)document.getElementById(focus)?.focus()}
function bindMarkets(){const input=document.getElementById('city'),box=document.getElementById('city-results');if(!input)return;function suggestions(){const q=input.value.trim().toLowerCase(),matches=q?marketRegistry.map((m,i)=>({m,i})).filter(({m})=>m.l.toLowerCase().includes(q)||m.city.toLowerCase().includes(q)||m.state.toLowerCase().includes(q)).slice(0,8):[];box.innerHTML=matches.map(({m,i})=>`<button type="button" class="search-results__item" role="option" aria-selected="false" data-city="${i}">${E(m.l)}</button>`).join('');box.hidden=!matches.length;input.setAttribute('aria-expanded',String(matches.length>0));box.querySelectorAll('[data-city]').forEach(b=>{b.onclick=()=>{const city=marketRegistry[Number(b.dataset.city)].l;state.requirements.city=city;state.requirements.district='';clearResultState();if(state.brief)refreshEditing('city');else {render();document.getElementById('city').focus()}};b.onkeydown=e=>{const list=Array.from(box.querySelectorAll('button')),i=list.indexOf(b);if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();list[(i+(e.key==='ArrowDown'?1:-1)+list.length)%list.length]?.focus()}if(e.key==='Escape'){box.hidden=true;input.setAttribute('aria-expanded','false');input.focus()}}})}input.onfocus=suggestions;input.oninput=()=>{const f=document.getElementById('answers');collectForm(f);state.requirements.district='';clearResultState();if(state.brief){refreshEditing('city');document.getElementById('city').dispatchEvent(new Event('focus'))}else {persist();suggestions()}};input.onkeydown=e=>{if(e.key==='ArrowDown'&&!box.hidden){e.preventDefault();box.querySelector('button')?.focus()}if(e.key==='Escape'){box.hidden=true;input.setAttribute('aria-expanded','false')}}}
function bind(){document.getElementById('home').onclick=e=>{e.preventDefault();beginSearch()};document.getElementById('reset').onclick=beginSearch;const f=document.getElementById('answers');document.querySelectorAll('[data-type]').forEach(b=>b.onclick=()=>{collectForm(f);changeType(b.dataset.type)});f.onsubmit=async e=>{e.preventDefault();if(!state.requirements.type||!f.reportValidity())return;collectForm(f);try{await syncBrief()}catch(error){state.notice=error.message;let p=document.getElementById('entry-error');if(!p){p=document.createElement('p');p.id='entry-error';p.setAttribute('role','alert');f.append(p)}p.textContent=error.message;return}state.brief=true;state.more=0;state.notice='Your starting points are ready. Nothing has been sent.';render();document.querySelector('#app h1').setAttribute('tabindex','-1');document.querySelector('#app h1').focus();window.scrollTo(0,0)};f.onchange=e=>{if(e.target.id==='city')return;if(!e.target.checkValidity())return;collectForm(f);retainCompatibleFeedback();if(state.brief)refreshEditing(e.target.id);else persist()};f.oninput=e=>{if(['people','size'].includes(e.target.id)&&e.target.checkValidity()){collectForm(f);retainCompatibleFeedback();if(state.brief)refreshEditing(e.target.id);else persist()}};document.querySelectorAll('[data-count]').forEach(b=>b.onclick=()=>{collectForm(f);state.requirements.people=b.dataset.count==='unknown'?null:Number(b.dataset.count);retainCompatibleFeedback();if(state.brief)refreshEditing();else render();document.querySelector('[data-count="'+b.dataset.count+'"]')?.focus()});const su=document.getElementById('size-unknown');if(su)su.onclick=()=>{collectForm(f);state.requirements.size=null;if(state.brief)refreshEditing('size');else render()};const clear=document.getElementById('clear-district');if(clear)clear.onclick=()=>{state.requirements.district='';clearResultState();if(state.brief)refreshEditing();else render()};const back=document.getElementById('back-brief');if(back)back.onclick=async()=>{try{await syncBrief();await refreshRequests()}catch(e){state.notice=e.message;render();return}document.getElementById('editbox').open=false;document.querySelector('#app h1').setAttribute('tabindex','-1');document.querySelector('#app h1').focus()};bindMarkets();document.querySelectorAll('[data-filter],[data-district]').forEach(b=>b.onclick=()=>{state.district=b.dataset.filter||b.dataset.district;inquiryRows=[];state.more=0;state.notice=state.district==='all'?'Showing all suggested areas.':'Showing researched starting points in '+districtNames[state.district]+'.';render();document.querySelector('[data-filter="'+state.district+'"]')?.focus()});document.querySelectorAll('[data-format]').forEach(b=>b.onclick=()=>{state.format=b.dataset.format;retainCompatibleFeedback();state.notice='Workspace format updated. We won’t substitute another format to fill the list.';render();document.querySelector('[data-format="'+state.format+'"]')?.focus()});for(const type of ['save','compare','dismiss'])document.querySelectorAll('[data-'+type+']').forEach(b=>b.onclick=()=>{const id=b.dataset[type],arr=type==='save'?state.saved:type==='compare'?state.compare:state.dismissed,i=arr.indexOf(id);if(i>=0)arr.splice(i,1);else arr.push(id);if(type==='dismiss'){state.saved=state.saved.filter(x=>x!==id);state.compare=state.compare.filter(x=>x!==id)}state.notice=type==='dismiss'?'Removed from your starting points. Another supported option appears where we have one.':type==='compare'?'Comparison updated below.':(i>=0?'Removed from saved options.':'Saved in this tab. No account or email needed.');render();document.querySelector(type==='dismiss'?'[data-help]':'[data-'+type+'="'+id+'"]')?.focus()});document.querySelectorAll('[data-help]').forEach(b=>b.onclick=()=>openHelp(b.dataset.help));const more=document.getElementById('more');if(more)more.onclick=()=>{state.more=state.more?0:4;state.notice=state.more?'Here are other options already supported by our research.':'Back to your first starting points.';render()};const restore=document.getElementById('restore');if(restore)restore.onclick=()=>{state.dismissed=[];state.more=0;state.notice='Dismissed options restored.';render()};const q=document.getElementById('rofo-question');if(q)q.onsubmit=e=>{e.preventDefault();previewQuestion(q)};bindRequests()}
const boot=JSON.parse(document.getElementById('universal-boot').textContent||'{}');
let liveBrief=boot.publicId?{publicId:boot.publicId,revision:boot.revision}:null,inquiryRows=[],saving=null,lastSaved=boot.requirement?JSON.stringify(boot.requirement.initialSearch):null;
function entryParameters(){const q=new URLSearchParams(location.search);if(!q.has('entry'))q.set('entry',q.get('source')==='homepage'?'home':q.get('source')||'home');if(!q.has('type')){const t=q.get('propertyType')||q.get('spaceType')||'';if(t)q.set('type',/retail|service/i.test(t)?'retail':/^flex$/i.test(t)?'flex':/industrial|warehouse/i.test(t)?'industrial':/office/i.test(t)?'office':'')}const district=q.get('districtId')||q.get('district');if(district){const id=Object.keys(districtNames).find(k=>k===district||districtNames[k].toLowerCase()===district.toLowerCase());if(id)q.set('district',id)}const c=q.get('city');if(c&&!/,\s*[A-Z]{2}$/.test(c)){const m=marketRegistry.find(x=>x.city.toLowerCase()===c.toLowerCase()&&(!q.get('state')||x.state===q.get('state')));if(m)q.set('city',m.l)}return q;}
async function requestApi(data){const response=await fetch('/api/universal-tenant',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(data)});const result=await response.json();if(!response.ok)throw new Error(result.error||'Please try again.');return result;}
async function syncBrief(){const form=document.getElementById('answers');if(form&&!form.reportValidity())throw new Error('Check your answers before saving your Brief.');if(form)collectForm(form);if(saving)return saving;if(liveBrief&&JSON.stringify(state.requirements)===lastSaved)return liveBrief;const snapshot=JSON.stringify(state.requirements);saving=(async()=>{const result=await requestApi({action:'save',requirements:JSON.parse(snapshot),originalEntry:entryOrigin,...liveBrief});liveBrief={publicId:result.publicId,revision:result.revision};lastSaved=JSON.stringify(result.requirement.initialSearch);if(JSON.stringify(state.requirements)===snapshot)state.requirements=result.requirement.initialSearch;history.replaceState(null,'','/location-brief/'+result.publicId);storageKey='rofoUniversalEntry:'+location.pathname;persist();return result})().finally(()=>saving=null);return saving;}
async function refreshRequests(){if(!liveBrief)return;const response=await fetch('/api/universal-tenant?brief='+encodeURIComponent(liveBrief.publicId));if(!response.ok)throw new Error('Reopen your Brief to view your requests.');const data=await response.json();inquiryRows=data.inquiries||[];}
function shareSummary(p){return `<dl class="sharing"><dt>Reply email</dt><dd>${E(p.replyEmail||p.email)}</dd><dt>Your search</dt><dd>${E(p.requirements?requirementsText(p.requirements):p.answers)}</dd><dt>Option</dt><dd>${E(p.option?.name||p.option||'Your current search')}</dd><dt>Approximate budget</dt><dd>${E(p.budget||'Not specified')}</dd><dt>Flexibility</dt><dd>${E(p.term||'Not specified')}</dd><dt>Growth</dt><dd>${E(p.growth||'Not specified')}</dd><dt>Additional requirements / questions</dt><dd>${E(p.message||p.note||'None')}</dd></dl>`}
function showRequest(payload,p){dialog.innerHTML=`<button class="close" aria-label="Close">×</button><h2 id="helpTitle">You decide what happens next.</h2><p>Your request stays with Rofo. We’ll identify an appropriate contact and ask separately before sharing outside Rofo.</p>${shareSummary(payload)}<p>Availability, pricing and a tour are not confirmed. Nothing is sent automatically. Rofo reviews your request first.</p><button class="primary" id="save-rofo">Ask Rofo to review</button><button class="quiet" id="decline">${E(COPY.decline)}</button><p role="status" id="request-status"></p>`;dialog.querySelector('.close').onclick=closeHelp;document.getElementById('decline').onclick=closeHelp;const key=crypto.randomUUID();document.getElementById('save-rofo').onclick=async e=>{e.target.disabled=true;try{await syncBrief();const result=await requestApi({action:'interest',...liveBrief,requestKey:key,email:payload.email,purpose:payload.purpose==='broker'?'professional':payload.purpose,itemId:p?.id||'',message:payload.note,budget:payload.budget,term:payload.term,growth:payload.growth});await refreshRequests();closeHelp();state.notice=result.notice;render()}catch(error){document.getElementById('request-status').textContent=error.message;e.target.disabled=false}};}
function previewQuestion(form){const data=new FormData(form),email=data.get('email'),message=data.get('question')||data.get('message');const status=document.getElementById('question-status');status.innerHTML='<p>Your question stays with Rofo and carries your current Brief. No introduction is authorized.</p><button type="button" class="primary" id="save-question">Ask Rofo to review</button>';const key=crypto.randomUUID();document.getElementById('save-question').onclick=async e=>{e.target.disabled=true;try{await syncBrief();const result=await requestApi({action:'question',...liveBrief,email,message,requestKey:key});await refreshRequests();state.notice=result.notice;render()}catch(error){status.textContent=error.message}};}
function requestMarkup(){if(!state.brief||!inquiryRows.length)return '';if(JSON.stringify(state.requirements)!==lastSaved)return '<section class="panel"><p>Your answers changed. Save your Brief before reviewing an introduction.</p></section>';return `<section class="panel"><h2>Your requests to Rofo</h2><p>These requests stay with Rofo until any separate introduction is approved.</p>${inquiryRows.map(r=>{const role=r.recipient?.role==='operator'?'operates this workspace':r.recipient?.role==='landlord'?'represents the landlord':'could represent you';return `<article><h3>${E(purposeLabel(r.purpose))}</h3><p>${E(statusLabel(r.status))}</p>${r.recipient&&r.status==='awaiting-permission'?`<h3>${E(COPY['intro-heading'])}</h3><p>${E(COPY['intro-permission'])}</p><p>${E(COPY['recipient-variable'].replace('[specific approved details]','reply email and the search details below').replace('[named recipient]',r.recipient.name+' ('+r.recipient.email+')').replace('[represents the landlord / operates this workspace / could represent you]',role))}</p><p><strong>Purpose:</strong> ${E(purposeLabel(r.purpose))}</p>${shareSummary(r.payload)}<p>Rofo may receive compensation for a permitted introduction. There’s no obligation; you can decline and keep exploring.</p><label class="check"><input type="checkbox" data-permission="${E(r.id)}">I permit sharing exactly the information above with the named recipient, for this purpose.</label><button disabled data-consent="${E(r.id)}">${E(COPY['intro-button'])}</button>`:''}<button class="quiet" data-withdraw="${E(r.id)}">${E(COPY.decline)}</button></article>`}).join('')}</section>`}
function bindRequests(){document.querySelectorAll('[data-permission]').forEach(c=>c.onchange=()=>{document.querySelector('[data-consent="'+c.dataset.permission+'"]').disabled=!c.checked});for(const action of ['consent','withdraw'])document.querySelectorAll('[data-'+action+']').forEach(b=>b.onclick=async()=>{const id=b.dataset[action],row=inquiryRows.find(r=>r.id===id);try{await syncBrief();const result=await requestApi({action,...liveBrief,id,version:row.version,permission:action==='consent'});await refreshRequests();state.notice=result.notice;render()}catch(error){state.notice=error.message;await refreshRequests();render()}})}
(async()=>{try{const response=await fetch('/api/universal-tenant');if(!response.ok)throw Error('The candidate is not enabled.');const data=await response.json();catalog=data.catalog;marketRegistry=data.markets;initializeEntry();if(liveBrief)await refreshRequests();render()}catch(error){app.innerHTML='<h1>Your search is temporarily unavailable</h1><p>'+E(error.message)+'</p>'}})();

function requirementsText(r){return [typeLabels[r.type],r.city,r.type==='office'?(r.people===null?'Team size not sure':r.people+' people')+' · '+workspaceLabels[r.workspace]:r.type==='retail'?retailLabels[r.business]:[r.type==='industrial'?(r.size===null?'Size not sure':r.size+' sq ft'):'',useLabels[r.use]].filter(Boolean).join(' · ')].filter(Boolean).join(' · ')}
function purposeLabel(v){return {question:COPY['question-link'],availability:COPY['inquiry-availability'],pricing:COPY['inquiry-pricing'],tour:COPY['inquiry-tour'],professional:'Help from a commercial real estate professional',research:COPY['inquiry-alternatives']}[v]||'Your request'}
function statusLabel(v){return {'manual-outcome-pending':'Rofo is checking the manual introduction outcome. Contact Rofo for an update.','manually-shared':'Rofo recorded a manual introduction. Contact Rofo with any questions.','rofo-only':'Saved for Rofo to review.','awaiting-permission':'Please review the proposed introduction.','permission-recorded-no-dispatch':'Your permission is saved. Nothing has been shared outside Rofo.','withdrawn':'You declined this request. You can keep exploring.','needs-review':'Your search changed. Rofo needs to review this request again.'}[v]||'Rofo will review this request.'}

function beginSearch(){liveBrief=null;lastSaved=null;entryOrigin=Object.freeze({entry:'home',city:'',type:'',district:'',building:null});state.requirements=freshRequirements();state.brief=false;clearResultState();history.replaceState(null,'','/location-requirement/');storageKey='rofoUniversalEntry:/location-requirement/';render()}
